    $raw = "[{\"track_key\": \"hanuman_chalisa\", \"title_hindi\": \"\u0936\u094d\u0930\u0940 \u0939\u0928\u0941\u092e\u093e\u0928 \u091a\u093e\u0932\u0940\u0938\u093e\", \"title_english\": \"Shri Hanuman Chalisa\", \"subtitle_hindi\": \"\u0926\u094b\u0939\u093e \u090f\u0935\u0902 \u096a\u0966 \u091a\u094c\u092a\u093e\u0907\u092f\u093e\u0901 \u2022 \u0938\u0902\u0915\u091f \u092e\u094b\u091a\u0928\", \"duration_text\": \"9:45\", \"audio_url\": \"https://shribalajikripadham.online/uploads/audio/sbkd_audio_1791373303_b758f0.mp3\", \"display_order\": 1, \"is_published\": 1, \"youtube_search_query\": \"Shri Hanuman Chalisa Hariharan Gulshan Kumar\", \"lyrics_hindi\": \"\u0965 \u0926\u094b\u0939\u093e \u0965\\n\u0936\u094d\u0930\u0940\u0917\u0941\u0930\u0941 \u091a\u0930\u0928 \u0938\u0930\u094b\u091c \u0930\u091c \u0928\u093f\u091c \u092e\u0928\u0941 \u092e\u0941\u0915\u0941\u0930\u0941 \u0938\u0941\u0927\u093e\u0930\u093f\u0964\\n\u092c\u0930\u0928\u090a\u0902 \u0930\u0918\u0941\u092c\u0930 \u092c\u093f\u092e\u0932 \u091c\u0938\u0941 \u091c\u094b \u0926\u093e\u092f\u0915\u0941 \u092b\u0932 \u091a\u093e\u0930\u093f\u0965\\n\u092c\u0941\u0926\u094d\u0927\u093f\u0939\u0940\u0928 \u0924\u0928\u0941 \u091c\u093e\u0928\u093f\u0915\u0947 \u0938\u0941\u092e\u093f\u0930\u094c\u0902 \u092a\u0935\u0928-\u0915\u0941\u092e\u093e\u0930\u0964\\n\u092c\u0932 \u092c\u0941\u0926\u094d\u0927\u093f \u092c\u093f\u0926\u094d\u092f\u093e \u0926\u0947\u0939\u0941 \u092e\u094b\u0939\u093f\u0902 \u0939\u0930\u0939\u0941 \u0915\u0932\u0947\u0938 \u092c\u093f\u0915\u093e\u0930\u0965\\n\\n\u0965 \u091a\u094c\u092a\u093e\u0908 \u0965\\n\u091c\u092f \u0939\u0928\u0941\u092e\u093e\u0928 \u091c\u094d\u091e\u093e\u0928 \u0917\u0941\u0928 \u0938\u093e\u0917\u0930\u0964\\n\u091c\u092f \u0915\u092a\u0940\u0938 \u0924\u093f\u0939\u0941\u0902 \u0932\u094b\u0915 \u0909\u091c\u093e\u0917\u0930\u0965\\n\u0930\u093e\u092e\u0926\u0942\u0924 \u0905\u0924\u0941\u0932\u093f\u0924 \u092c\u0932 \u0927\u093e\u092e\u093e\u0964\\n\u0905\u0902\u091c\u0928\u093f-\u092a\u0941\u0924\u094d\u0930 \u092a\u0935\u0928\u0938\u0941\u0924 \u0928\u093e\u092e\u093e\u0965\\n\\n\u092e\u0939\u093e\u092c\u0940\u0930 \u092c\u093f\u0915\u094d\u0930\u092e \u092c\u091c\u0930\u0902\u0917\u0940\u0964\\n\u0915\u0941\u092e\u0924\u093f \u0928\u093f\u0935\u093e\u0930 \u0938\u0941\u092e\u0924\u093f \u0915\u0947 \u0938\u0902\u0917\u0940\u0965\\n\u0915\u0902\u091a\u0928 \u092c\u0930\u0928 \u092c\u093f\u0930\u093e\u091c \u0938\u0941\u092c\u0947\u0938\u093e\u0964\\n\u0915\u093e\u0928\u0928 \u0915\u0941\u0902\u0921\u0932 \u0915\u0941\u0902\u091a\u093f\u0924 \u0915\u0947\u0938\u093e\u0965\\n\\n\u0939\u093e\u0925 \u092c\u091c\u094d\u0930 \u0914 \u0927\u094d\u0935\u091c\u093e \u092c\u093f\u0930\u093e\u091c\u0948\u0964\\n\u0915\u093e\u0902\u0927\u0947 \u092e\u0942\u0902\u091c \u091c\u0928\u0947\u090a \u0938\u093e\u091c\u0948\u0965\\n\u0938\u0902\u0915\u0930 \u0938\u0941\u0935\u0928 \u0915\u0947\u0938\u0930\u0940\u0928\u0902\u0926\u0928\u0964\\n\u0924\u0947\u091c \u092a\u094d\u0930\u0924\u093e\u092a \u092e\u0939\u093e \u091c\u0917 \u092c\u0928\u094d\u0926\u0928\u0965\\n\\n\u092c\u093f\u0926\u094d\u092f\u093e\u0935\u093e\u0928 \u0917\u0941\u0928\u0940 \u0905\u0924\u093f \u091a\u093e\u0924\u0941\u0930\u0964\\n\u0930\u093e\u092e \u0915\u093e\u091c \u0915\u0930\u093f\u092c\u0947 \u0915\u094b \u0906\u0924\u0941\u0930\u0965\\n\u092a\u094d\u0930\u092d\u0941 \u091a\u0930\u093f\u0924\u094d\u0930 \u0938\u0941\u0928\u093f\u092c\u0947 \u0915\u094b \u0930\u0938\u093f\u092f\u093e\u0964\\n\u0930\u093e\u092e \u0932\u0916\u0928 \u0938\u0940\u0924\u093e \u092e\u0928 \u092c\u0938\u093f\u092f\u093e\u0965\\n\\n\u0938\u0942\u0915\u094d\u0937\u094d\u092e \u0930\u0942\u092a \u0927\u0930\u093f \u0938\u093f\u092f\u0939\u093f\u0902 \u0926\u093f\u0916\u093e\u0935\u093e\u0964\\n\u092c\u093f\u0915\u091f \u0930\u0942\u092a \u0927\u0930\u093f \u0932\u0902\u0915 \u091c\u0930\u093e\u0935\u093e\u0965\\n\u092d\u0940\u092e \u0930\u0942\u092a \u0927\u0930\u093f \u0905\u0938\u0941\u0930 \u0938\u0902\u0939\u093e\u0930\u0947\u0964\\n\u0930\u093e\u092e\u091a\u0902\u0926\u094d\u0930 \u0915\u0947 \u0915\u093e\u091c \u0938\u0902\u0935\u093e\u0930\u0947\u0965\\n\\n\u0932\u093e\u092f \u0938\u0902\u091c\u0940\u0935\u0928 \u0932\u0916\u0928 \u091c\u093f\u092f\u093e\u092f\u0947\u0964\\n\u0936\u094d\u0930\u0940\u0930\u0918\u0941\u092c\u0940\u0930 \u0939\u0930\u0937\u093f \u0909\u0930 \u0932\u093e\u092f\u0947\u0965\\n\u0930\u0918\u0941\u092a\u0924\u093f \u0915\u0940\u0928\u094d\u0939\u0940 \u092c\u0939\u0941\u0924 \u092c\u0921\u093c\u093e\u0908\u0964\\n\u0924\u0941\u092e \u092e\u092e \u092a\u094d\u0930\u093f\u092f \u092d\u0930\u0924\u0939\u093f \u0938\u092e \u092d\u093e\u0908\u0965\\n\\n\u0938\u0939\u0938 \u092c\u0926\u0928 \u0924\u0941\u092e\u094d\u0939\u0930\u094b \u091c\u0938 \u0917\u093e\u0935\u0948\u0902\u0964\\n\u0905\u0938 \u0915\u0939\u093f \u0936\u094d\u0930\u0940\u092a\u0924\u093f \u0915\u0902\u0920 \u0932\u0917\u093e\u0935\u0948\u0902\u0965\\n\u0938\u0928\u0915\u093e\u0926\u093f\u0915 \u092c\u094d\u0930\u0939\u094d\u092e\u093e\u0926\u093f \u092e\u0941\u0928\u0940\u0938\u093e\u0964\\n\u0928\u093e\u0930\u0926 \u0938\u093e\u0930\u0926 \u0938\u0939\u093f\u0924 \u0905\u0939\u0940\u0938\u093e\u0965\\n\\n\u091c\u092e \u0915\u0941\u092c\u0947\u0930 \u0926\u093f\u0917\u092a\u093e\u0932 \u091c\u0939\u093e\u0902 \u0924\u0947\u0964\\n\u0915\u092c\u093f \u0915\u094b\u092c\u093f\u0926 \u0915\u0939\u093f \u0938\u0915\u0947 \u0915\u0939\u093e\u0902 \u0924\u0947\u0965\\n\u0924\u0941\u092e \u0909\u092a\u0915\u093e\u0930 \u0938\u0941\u0917\u094d\u0930\u0940\u0935\u0939\u093f\u0902 \u0915\u0940\u0928\u094d\u0939\u093e\u0964\\n\u0930\u093e\u092e \u092e\u093f\u0932\u093e\u092f \u0930\u093e\u091c \u092a\u0926 \u0926\u0940\u0928\u094d\u0939\u093e\u0965\\n\\n\u0924\u0941\u092e\u094d\u0939\u0930\u094b \u092e\u0902\u0924\u094d\u0930 \u092c\u093f\u092d\u0940\u0937\u0928 \u092e\u093e\u0928\u093e\u0964\\n\u0932\u0902\u0915\u0947\u0938\u094d\u0935\u0930 \u092d\u090f \u0938\u092c \u091c\u0917 \u091c\u093e\u0928\u093e\u0965\\n\u091c\u0941\u0917 \u0938\u0939\u0938\u094d\u0930 \u091c\u094b\u091c\u0928 \u092a\u0930 \u092d\u093e\u0928\u0942\u0964\\n\u0932\u0940\u0932\u094d\u092f\u094b \u0924\u093e\u0939\u093f \u092e\u0927\u0941\u0930 \u092b\u0932 \u091c\u093e\u0928\u0942\u0965\\n\\n\u092a\u094d\u0930\u092d\u0941 \u092e\u0941\u0926\u094d\u0930\u093f\u0915\u093e \u092e\u0947\u0932\u093f \u092e\u0941\u0916 \u092e\u093e\u0939\u0940\u0902\u0964\\n\u091c\u0932\u0927\u093f \u0932\u093e\u0902\u0918\u093f \u0917\u092f\u0947 \u0905\u091a\u0930\u091c \u0928\u093e\u0939\u0940\u0902\u0965\\n\u0926\u0941\u0930\u094d\u0917\u092e \u0915\u093e\u091c \u091c\u0917\u0924 \u0915\u0947 \u091c\u0947\u0924\u0947\u0964\\n\u0938\u0941\u0917\u092e \u0905\u0928\u0941\u0917\u094d\u0930\u0939 \u0924\u0941\u092e\u094d\u0939\u0930\u0947 \u0924\u0947\u0924\u0947\u0965\\n\\n\u0930\u093e\u092e \u0926\u0941\u0906\u0930\u0947 \u0924\u0941\u092e \u0930\u0916\u0935\u093e\u0930\u0947\u0964\\n\u0939\u094b\u0924 \u0928 \u0906\u091c\u094d\u091e\u093e \u092c\u093f\u0928\u0941 \u092a\u0948\u0938\u093e\u0930\u0947\u0965\\n\u0938\u092c \u0938\u0941\u0916 \u0932\u0939\u0948 \u0924\u0941\u092e\u094d\u0939\u093e\u0930\u0940 \u0938\u0930\u0928\u093e\u0964\\n\u0924\u0941\u092e \u0930\u0915\u094d\u0937\u0915 \u0915\u093e\u0939\u0942 \u0915\u094b \u0921\u0930 \u0928\u093e\u0965\\n\\n\u0906\u092a\u0928 \u0924\u0947\u091c \u0938\u092e\u094d\u0939\u093e\u0930\u094b \u0906\u092a\u0948\u0964\\n\u0924\u0940\u0928\u094b\u0902 \u0932\u094b\u0915 \u0939\u093e\u0902\u0915 \u0924\u0947\u0902 \u0915\u093e\u0902\u092a\u0948\u0965\\n\u092d\u0942\u0924 \u092a\u093f\u0938\u093e\u091a \u0928\u093f\u0915\u091f \u0928\u0939\u093f\u0902 \u0906\u0935\u0948\u0964\\n\u092e\u0939\u093e\u092c\u0940\u0930 \u091c\u092c \u0928\u093e\u092e \u0938\u0941\u0928\u093e\u0935\u0948\u0965\\n\\n\u0928\u093e\u0938\u0948 \u0930\u094b\u0917 \u0939\u0930\u0948 \u0938\u092c \u092a\u0940\u0930\u093e\u0964\\n\u09