902 \u091c\u093e\u0928\u0924 \u0939\u0948 \u091c\u0917 \u092e\u0947\u0902 \u0915\u092a\u093f,\\n\u0938\u0902\u0915\u091f\u092e\u094b\u091a\u0928 \u0928\u093e\u092e \u0924\u093f\u0939\u093e\u0930\u094b\u0965 \u0967 \u0965\\n\\n\u092c\u093e\u0932\u093f \u0915\u0940 \u0924\u094d\u0930\u093e\u0938 \u0915\u092a\u0940\u0938 \u092c\u0938\u0948 \u0917\u093f\u0930\u093f,\\n\u091c\u093e\u0924 \u092e\u0939\u093e\u092a\u094d\u0930\u092d\u0941 \u092a\u0902\u0925 \u0928\u093f\u0939\u093e\u0930\u094b\u0964\\n\u091a\u094c\u0902\u0915\u093f \u092e\u0939\u093e\u092e\u0941\u0928\u093f \u0938\u093e\u092a \u0926\u093f\u092f\u094b \u0924\u092c,\\n\u091a\u093e\u0939\u093f\u090f \u0915\u094c\u0928 \u092c\u093f\u091a\u093e\u0930 \u092c\u093f\u091a\u093e\u0930\u094b\u0964\\n\u0915\u0948 \u0926\u094d\u0935\u093f\u091c \u0930\u0942\u092a \u0932\u093f\u0935\u093e\u092f \u092e\u0939\u093e\u092a\u094d\u0930\u092d\u0941,\\n\u0938\u094b \u0924\u0941\u092e \u0926\u093e\u0938 \u0915\u0947 \u0938\u094b\u0915 \u0928\u093f\u0935\u093e\u0930\u094b\u0964\\n\u0915\u094b \u0928\u0939\u093f\u0902 \u091c\u093e\u0928\u0924 \u0939\u0948 \u091c\u0917 \u092e\u0947\u0902 \u0915\u092a\u093f,\\n\u0938\u0902\u0915\u091f\u092e\u094b\u091a\u0928 \u0928\u093e\u092e \u0924\u093f\u0939\u093e\u0930\u094b\u0965 \u0968 \u0965\\n\\n\u0905\u0902\u0917\u0926 \u0915\u0947 \u0938\u0902\u0917 \u0932\u0947\u0928 \u0917\u090f \u0938\u093f\u092f,\\n\u0916\u094b\u091c \u0915\u092a\u0940\u0938 \u092f\u0939 \u092c\u0948\u0928 \u0909\u091a\u093e\u0930\u094b\u0964\\n\u091c\u0940\u0935\u0924 \u0928\u093e \u092c\u091a\u093f\u0939\u094c \u0939\u092e \u0938\u094b \u091c\u0941,\\n\u092c\u093f\u0928\u093e \u0938\u0941\u0927\u093f \u0932\u093e\u092f\u0947 \u0907\u0939\u093e\u0902 \u092a\u0917\u0941 \u0927\u093e\u0930\u094b\u0964\\n\u0939\u0947\u0930\u0940 \u0925\u0915\u0947 \u0924\u091f \u0938\u093f\u0902\u0927\u0941 \u0938\u092c\u0947 \u0924\u092c,\\n\u0932\u093e\u090f \u0938\u093f\u092f\u093e-\u0938\u0941\u0927\u093f \u092a\u094d\u0930\u093e\u0928 \u0909\u092c\u093e\u0930\u094b\u0964\\n\u0915\u094b \u0928\u0939\u093f\u0902 \u091c\u093e\u0928\u0924 \u0939\u0948 \u091c\u0917 \u092e\u0947\u0902 \u0915\u092a\u093f,\\n\u0938\u0902\u0915\u091f\u092e\u094b\u091a\u0928 \u0928\u093e\u092e \u0924\u093f\u0939\u093e\u0930\u094b\u0965 \u0969 \u0965\\n\\n\u0930\u093e\u0935\u0928 \u0924\u094d\u0930\u093e\u0938 \u0926\u0908 \u0938\u093f\u092f \u0915\u094b \u0938\u092c,\\n\u0930\u093e\u0915\u094d\u0937\u0938\u093f \u0938\u094b\u0902 \u0915\u0939\u093f \u0938\u094b\u0915 \u0928\u093f\u0935\u093e\u0930\u094b\u0964\\n\u0924\u093e\u0939\u093f \u0938\u092e\u092f \u0939\u0928\u0941\u092e\u093e\u0928 \u092e\u0939\u093e\u092a\u094d\u0930\u092d\u0941,\\n\u091c\u093e\u092f \u092e\u0939\u093e \u0930\u091c\u0928\u0940\u091a\u0930 \u092e\u093e\u0930\u094b\u0964\\n\u091a\u093e\u0939\u0924 \u0938\u0940\u092f \u0905\u0938\u094b\u0915 \u0938\u094b\u0902 \u0906\u0917\u093f \u0938\u0941,\\n\u0926\u0948 \u092a\u094d\u0930\u092d\u0941 \u092e\u0941\u0926\u094d\u0930\u093f\u0915\u093e \u0938\u094b\u0915 \u0928\u093f\u0935\u093e\u0930\u094b\u0964\\n\u0915\u094b \u0928\u0939\u093f\u0902 \u091c\u093e\u0928\u0924 \u0939\u0948 \u091c\u0917 \u092e\u0947\u0902 \u0915\u092a\u093f,\\n\u0938\u0902\u0915\u091f\u092e\u094b\u091a\u0928 \u0928\u093e\u092e \u0924\u093f\u0939\u093e\u0930\u094b\u0965 \u096a \u0965\\n\\n\u092c\u093e\u0928 \u0932\u0917\u094d\u092f\u094b \u0909\u0930 \u0932\u091b\u093f\u092e\u0928 \u0915\u0947 \u0924\u092c,\\n\u092a\u094d\u0930\u093e\u0928 \u0924\u091c\u0947 \u0938\u0941\u0924 \u0930\u093e\u0935\u0928 \u092e\u093e\u0930\u094b\u0964\\n\u0932\u0948 \u0917\u0943\u0939 \u092c\u0948\u0926\u094d\u092f \u0938\u0941\u0937\u0947\u0928 \u0938\u092e\u0947\u0924,\\n\u0924\u092c\u0948 \u0917\u093f\u0930\u093f \u0926\u094d\u0930\u094b\u0923 \u0938\u0941 \u092c\u0940\u0930 \u0909\u092a\u093e\u0930\u094b\u0964\\n\u0906\u0928\u093f \u0938\u0902\u091c\u0940\u0935\u0928 \u0939\u093e\u0925 \u0926\u0908 \u0924\u092c,\\n\u0932\u091b\u093f\u092e\u0928 \u0915\u0947 \u0924\u0941\u092e \u092a\u094d\u0930\u093e\u0928 \u0909\u092c\u093e\u0930\u094b\u0964\\n\u0915\u094b \u0928\u0939\u093f\u0902 \u091c\u093e\u0928\u0924 \u0939\u0948 \u091c\u0917 \u092e\u0947\u0902 \u0915\u092a\u093f,\\n\u0938\u0902\u0915\u091f\u092e\u094b\u091a\u0928 \u0928\u093e\u092e \u0924\u093f\u0939\u093e\u0930\u094b\u0965 \u096b \u0965\\n\\n\u0930\u093e\u0935\u0928 \u091c\u0941\u0926\u094d\u0927 \u0905\u091c\u093e\u0928 \u0915\u093f\u092f\u094b \u0924\u092c,\\n\u0928\u093e\u0917 \u0915\u093f \u092b\u093e\u0902\u0938 \u0938\u092c\u0948 \u0938\u093f\u0930 \u0921\u093e\u0930\u094b\u0964\\n\u0936\u094d\u0930\u0940\u0930\u0918\u0941\u0928\u093e\u0925 \u0938\u092e\u0947\u0924 \u0938\u092c\u0948 \u0926\u0932,\\n\u092e\u094b\u0939 \u092d\u092f\u094b \u092f\u0939 \u0938\u0902\u0915\u091f \u092d\u093e\u0930\u094b\u0964\\n\u0906\u0928\u093f \u0916\u0917\u0947\u0938 \u0924\u092c\u0948 \u0939\u0928\u0941\u092e\u093e\u0928 \u091c\u0941,\\n\u092c\u0902\u0927\u0928 \u0915\u093e\u091f\u093f \u0938\u0941\u0924\u094d\u0930\u093e\u0938 \u0928\u093f\u0935\u093e\u0930\u094b\u0964\\n\u0915\u094b \u0928\u0939\u093f\u0902 \u091c\u093e\u0928\u0924 \u0939\u0948 \u091c\u0917 \u092e\u0947\u0902 \u0915\u092a\u093f,\\n\u0938\u0902\u0915\u091f\u092e\u094b\u091a\u0928 \u0928\u093e\u092e \u0924\u093f\u0939\u093e\u0930\u094b\u0965 \u096c \u0965\\n\\n\u092c\u0902\u0927\u0941 \u0938\u092e\u0947\u0924 \u091c\u092c\u0948 \u0905\u0939\u093f\u0930\u093e\u0935\u0928,\\n\u0932\u0948 \u0930\u0918\u0941\u0928\u093e\u0925 \u092a\u0924\u093e\u0930 \u0938\u093f\u0927\u093e\u0930\u094b\u0964\\n\u0926\u0947\u092c\u093f\u0939\u093f\u0902 \u092a\u0942\u091c\u093f \u092d\u0932\u0940 \u092c\u093f\u0927\u093f \u0938\u094b\u0902 \u092c\u0932\u093f,\\n\u0926\u0947\u0909 \u0938\u092c\u0948 \u092e\u093f\u0932\u093f \u092e\u0902\u0924\u094d\u0930 \u092c\u093f\u091a\u093e\u0930\u094b\u0964\\n\u091c\u093e\u092f \u0938\u0939\u093e\u092f \u092d\u092f\u094b \u0924\u092c \u0939\u0940,\\n\u0905\u0939\u093f\u0930\u093e\u0935\u0928 \u0938\u0948\u0928\u094d\u092f \u0938\u092e\u0947\u0924 \u0938\u0902\u0939\u093e\u0930\u094b\u0964\\n\u0915\u094b \u0928\u0939\u093f\u0902 \u091c\u093e\u0928\u0924 \u0939\u0948 \u091c\u0917 \u092e\u0947\u0902 \u0915\u092a\u093f,\\n\u0938\u0902\u0915\u091f\u092e\u094b\u091a\u0928 \u0928\u093e\u092e \u0924\u093f\u0939\u093e\u0930\u094b\u0965 \u096d \u0965\\n\\n\u0915\u093e\u091c \u0915\u093f\u092f\u0947 \u092c\u0921\u093c \u0926\u0947\u0935\u0928 \u0915\u0947 \u0924\u0941\u092e,\\n\u092c\u0940\u0930 \u092e\u0939\u093e\u092a\u094d\u0930\u092d\u0941 \u0926\u0947\u0916\u093f \u092c\u093f\u091a\u093e\u0930\u094b\u0964\\n\u0915\u094c\u0928 \u0938\u094b \u0938\u0902\u0915\u091f \u092e\u094b\u0930 \u0917\u0930\u0940\u092c \u0915\u094b,\\n\u091c\u094b \u0924\u0941\u092e\u0938\u094b\u0902 \u0928\u0939\u093f\u0902 \u091c\u093e\u0924 \u0939\u0948 \u091f\u093e\u0930\u094b\u0964\\n\u092c\u0947\u0917\u093f \u0939\u0930\u094b \u0939\u0928\u0941\u092e\u093e\u0928 \u092e\u0939\u093e\u092a\u094d\u0930\u092d\u0941,\\n\u091c\u094b \u0915\u091b\u0941 \u0938\u0902\u0915\u091f \u0939\u094b\u092f \u0939\u092e\u093e\u0930\u094b\u0964\\n\u0915\u094b \u0928\u0939\u093f\u0902 \u091c\u093e\u0928\u0924 \u0939\u0948 \u091c\u0917 \u092e\u0947\u0902 \u0915\u092a\u093f,\\n\u0938\u0902\u0915\u091f\u092e\u094b\u091a\u0928 \u0928\u093e\u092e \u0924\u093f\u0939\u093e\u0930\u094b\u0965 \u096e \u0965\\n\\n\u0965 \u0926\u094b\u0939\u093e \u0965\\n\u0932\u093e\u0932 \u0926\u0947\u0939 \u0932\u093e\u0932\u0940 \u0932\u0938\u0947, \u0905\u0930\u0941 \u0927\u0930\u093f \u0932\u093e\u0932 \u0932\u0902\u0917\u0942\u0930\u0964\\n\u092c\u091c\u094d\u0930 \u0926\u0947\u0939 \u0926\u093e\u0928\u0935 \u0926\u0932\u0928, \u091c\u092f \u091c\u092f \u091c\u092f \u0915\u092a\u093f \u0938\u0942\u0930\u0965\"}, {\"track_key\": \"bajrang_baan\", \"title_hindi\": \"\u0936\u094d\u0930\u0940 \u092c\u091c\u0930\u0902\u0917 \u092c\u093e\u0923\", \"title_english\": \"Shri Bajrang Baan\", \"subtitle_hindi\": \"\u0928\u093f\u0936\u094d\u091a\u092f \u092a\u094d\u0930\u0947\u092e \u092a\u094d\u0930\u0924\u0940\u0924\u093f \u0924\u0947, \u092c\u093f\u0928\u092f \u0915\u0930\u0948\u0902 \u0938\u0928\u092e\u093e\u0928...\", \"duration_text\": \"7:12\", \"audio_url\": \"https://shribalajikripadham.online/uploads/audio/sbkd_audio_1791373305_f87240.mp3\", \"display_order\": 5, \"is_published\": 1, \"youtube_search_query\": \"Shri Bajrang Baan Hariharan\", \"lyrics_hindi\": \"\u0965 \u0926\u094b\u0939\u093e \u0965\\n\u0928\u093f\u0936\u094d\u091a\u092f \u092a\u094d\u0930\u0947\u092e \u092a\u094d\u0930\u0924\u0940\u0924\u093f \u0924\u0947, \u092c\u093f\u0928\u092f \u0915\u0930\u0948\u0902 \u0938\u0928\u092e\u093e\u0928\u0964\\n\u0924\u0947\u0939\u093f \u0915\u0947 \u0915\u093e\u0930\u091c \u0938\u0915\u0932 \u0936\u0941\u092d, \u0938\u093f\u0926\u094d\u0927 \u0915\u0930\u0948\u0902 \u0939\u0928\u0941\u092e\u093e\u0928\u0965\\n\\n\u0965 \u091a\u094c\u092a\u093e\u0908 \u0965\\n\u091c\u092f \u0939\u0928\u0941\u092e\u0902\u0924 \u0938\u0902\u0924 \u0939\u093f\u0924\u0915\u093e\u0930\u0940\u0964\\n\u0938\u0941\u0928\u093f \u0932\u0940\u091c\u0948 \u092a\u094d\u0930\u092d\u0941 \u0905\u0930\u091c \u0939\u092e\u093e\u0930\u0940\u0965\\n\u091c\u0928 \u0915\u0947 \u0915\u093e\u091c \u092c\u093f\u0932\u0902\u092c \u0928 \u0915\u0940\u091c\u0948\u0964\\n\u0906\u0924\u0941\u0930 \u0926\u094c\u0930\u093f \u092e\u0939\u093e \u0938\u0941\u0916 \u0926\u0940\u091c\u0948\u0965\\n\\n\u091c\u0948\u0938\u0947 \u0915\u0942\u0926\u093f \u0938\u093f\u0902\u0927\u0941 \u092e\u0939\u093f\u092a\u093e\u0930\u093e\u0964\\n\u0938\u0941\u0930\u0938\u093e \u092c\u0926\u0928 \u092a\u0948\u0920\u093f \u092c\u093f\u0938\u094d\u0924\u093e\u0930\u093e\u0965\\n\u0906\u0917\u0947 \u091c\u093e\u092f \u0932\u0902\u0915\u093f\u0928\u0940 \u0930\u094b\u0915\u093e\u0964\\n\u092e\u093e\u0930\u0947\u0939\u0941 \u0932\u093e\u0924 \u0917\u0908 \u0938\u0941\u0930 \u0932\u094b\u0915\u093e\u0965\\n\\n\u091c\u093e\u092f \u092c\u093f\u092d\u0940\u0937\u0928 \u0915\u094b \u0938\u0941\u0916 \u0926\u0940\u0928\u094d\u0939\u093e\u0964\\n\u0938\u0940\u0924\u093e \u0928\u093f\u0930\u0916\u093f \u092a\u0930\u092e\u092a\u0926 \u0932\u0940\u0928\u094d\u0939\u093e\u0965\\n\u092c\u093e\u0917 \u0909\u091c\u093e\u0930\u093f \u0905\u091b\u092f \u0915\u0941\u092e\u093e\u0930\u093e\u0964\\n\u0915\u092a\u093f \u0938\u0902\u0939\u093e\u0930\u093f \u0932\u0902\u0915 \u092a\u0930 \u091c\u093e\u0930\u093e\u0965\\n\\n\u0932\u093e\u0939 \u0938\u092e\u093e\u0928 \u0932\u0902\u0915 \u091c\u0930\u093f \u0917\u0908\u0964\\n\u091c\u092f \u091c\u092f \u0927\u0941\u0928\u093f \u0938\u0941\u0930\u092a\u0941\u0930 \u0928\u092d \u092d\u0908\u0965\\n\u0905\u092c \u092c\u093f\u0932\u0902\u092c \u0915\u0947\u0939\u093f \u0915\u093e\u0930\u0928 \u0938\u094d\u0935\u093e\u092e\u0940\u0964\\n\u0915\u0943\u092a\u093e \u0915\u0930\u0939\u0941 \u0909\u0930 \u0905\u0902\u0924\u0930\u092f\u093e\u092e\u0940\u0965\\n\\n\u091c\u092f \u091c\u092f \u0932\u0916\u0928 \u092a\u094d\u0930\u093e\u0928 \u0915\u0947 \u0926\u093e\u0924\u093e\u0964\\n\u0906\u0924\u0941\u0930 \u0939\u094b\u0907 \u0926\u0941\u0916 \u0939\u0930\u0939\u0941 \u0928\u093f\u092a\u093e\u0924\u093e\u0965\\n\u091c\u0948 \u0917\u093f\u0930\u093f\u0927\u0930 \u091c\u0948 \u091c\u0948 \u0938\u0941\u0916\u0926\u093e\u0908\u0964\\n\u0938\u0947\u0935\u093e \u0915\u093f\u092f\u094b \u0938\u0941\u0917\u094d\u0930\u0940\u0935 \u0915\u0928\u094d\u0939\u093e\u0908\u0965\\n\\n\u0950 \u0939\u0928\u0941 \u0939\u0928\u0941 \u0939\u0928\u0941 \u0939\u0928\u0941\u092e\u0902\u0924 \u0939\u0920\u0940\u0932\u0947\u0964\\n\u092c\u0948\u0930\u093f\u0939\u093f \u092e\u093e\u0930\u0941 \u092c\u091c\u094d\u0930 \u0915\u0940 \u0915\u0940\u0932\u0947\u0965\\n\u0917\u0926\u093e \u092c\u091c\u094d\u0930 \u0932\u0948 \u092c\u0948\u0930\u093f\u0939\u093f \u092e\u093e\u0930\u094b\u0964\\n\u092e\u0939\u093e\u0930\u093e\u091c \u092a\u094d\u0930\u092d\u0941 \u0926\u093e\u0938 \u0909\u092c\u093e\u0930\u094b\u0965\\n\\n\u0950 \u0939\u094d\u0930\u0940\u0902 \u0939\u094d\u0930\u0940\u0902 \u0939\u094d\u0930\u0940\u0902 \u0939\u0928\u0941\u092e\u0902\u0924 \u0915\u092a\u0940\u0938\u093e\u0964\\n\u0950 \u0939\u0941\u0902 \u0939\u0941\u0902 \u0939\u0941\u0902 \u0939\u0928\u0941 \u0905\u0930\u093f \u0909\u0930 \u0938\u0940\u0938\u093e\u0965\\n\u0938\u0924\u094d\u092f \u0939\u094b\u0939\u0941 \u0939\u0930\u093f \u0938\u092a\u0925 \u092a\u093e\u092f\u0915\u0947\u0964\\n\u0930\u093e\u092e \u0926\u0942\u0924 \u0927\u0930\u0941 \u092e\u093e\u0930\u0941 \u0927\u093e\u092f\u0915\u0947\u0965\\n\\n\u091c\u092f \u091c\u092f \u091c\u092f \u0939\u0928\u0941\u092e\u0902\u0924 \u0905\u0917\u093e\u0927\u093e\u0964\\n\u0926\u0941\u0916 \u092a\u093e\u0935\u0924 \u091c\u0928 \u0915\u0947\u0939\u093f \u0905\u092a\u0930\u093e\u0927\u093e\u0965\\n\u092a\u0942\u091c\u093e \u091c\u092a \u0924\u092a \u0928\u0947\u092e \u0905\u091a\u093e\u0930\u093e\u0964\\n\u0928\u0939\u093f\u0902 \u091c\u093e\u0928\u0924 \u0915\u091b\u0941 \u0926\u093e\u0938 \u0924\u0941\u092e\u094d\u0939\u093e\u0930\u093e\u0965\\n\\n\u092c\u0928 \u0909\u092a\u092c\u0928 \u092e\u0917 \u0917\u093f\u0930\u093f \u0917\u0943\u0939 \u092e\u093e\u0939\u0940\u0902\u0964\\n\u0924\u0941\u092e\u094d\u0939\u0930\u0947 \u092c\u0932 \u0939\u092e \u0921\u0930\u092a\u0924 \u0928\u093e\u0939\u0940\u0902\u0965\\n\u091c\u0928\u0915\u0938\u0941\u0924\u093e \u0939\u0930\u093f \u0926\u093e\u0938 \u0915\u0939\u093e\u0935\u094b\u0964\\n\u0924\u093e\u0915\u0940 \u0938\u092a\u0925 \u092c\u093f\u0932\u0902\u092c \u0928 \u0932\u093e\u0935\u094b\u0965\\n\\n\u091c\u0948 \u091c\u0948 \u091c\u0948 \u0927\u0941\u0928\u093f \u0939\u094b\u0924 \u0905\u0915\u093e\u0938\u093e\u0964\\n\u0938\u0941\u092e\u093f\u0930\u0924 \u0939\u094b\u0924 \u0926\u0941\u0938\u0939 \u0926\u0941\u0916 \u0928\u093e\u0938\u093e\u0965\\n\u091a\u0930\u0928 \u092a\u0915\u0930\u093f \u0915\u0930 \u091c\u094b\u0930\u093f \u092e\u0928\u093e\u0935\u094c\u0902\u0964\\n\u092f\u0939\u093f \u0914\u0938\u0930 \u0905\u092c \u0915\u0947\u0939\u093f \u0917\u094b\u0939\u0930\u093e\u0935\u094c\u0902\u0965\\n\\n\u0909\u0920\u0941 \u0909\u0920\u0941 \u091a\u0932\u0941 \u0924\u094b\u0939\u093f \u0930\u093e\u092e \u0926\u0941\u0939\u093e\u0908\u0964\\n\u092a\u093e\u0902\u092f \u092a\u0930\u094c\u0902 \u0915\u0930 \u091c\u094b\u0930\u093f \u092e\u0928\u093e\u0908\u0965\\n\u0950 \u091a\u0902 \u091a\u0902 \u091a\u0902 \u091a\u0902 \u091a\u092a\u0932 \u091a\u0932\u0902\u0924\u093e\u0964\\n\u0950 \u0939\u0928\u0941 \u0939\u0928\u0941 \u0939\u0928\u0941 \u0939\u0928\u0941 \u0939\u0928\u0941\u092e\u0902\u0924\u093e\u0965\\n\\n\u0950 \u0939\u0902 \u0939\u0902 \u0939\u093e\u0902\u0915 \u0926\u0947\u0924 \u0915\u092a\u093f \u091a\u0902\u091a\u0932\u0964\\n\u0950 \u0938\u0902 \u0938\u0902 \u0938\u0939\u092e\u093f \u092a\u0930\u093e\u0928\u0947 \u0916\u0932-\u0926\u0932\u0965\\n\u0905\u092a\u0928\u0947 \u091c\u0928 \u0915\u094b \u0924\u0941\u0930\u0924 \u0909\u092c\u093e\u0930\u094b\u0964\\n\u0938\u0941\u092e\u093f\u0930\u0924 \u0939\u094b\u092f \u0906\u0928\u0902\u0926 \u0939\u092e\u093e\u0930\u094b\u0965\\n\\n\u092f\u0939 \u092c\u091c\u0930\u0902\u0917 \u092c\u093e\u0923 \u091c\u0947\u0939\u093f \u092e\u093e\u0930\u0948\u0964\\n\u0924\u093e\u0939\u093f \u0915\u0939\u094b \u092b\u093f\u0930\u093f \u0915\u0935\u0928 \u0909\u092c\u093e\u0930\u0948\u0965\\n\u092a\u093e\u0920 \u0915\u0930\u0948 \u092c\u091c\u0930\u0902\u0917 \u092c\u093e\u0923 \u0915\u0940\u0964\\n\u0939\u0928\u0941\u092e\u0924 \u0930\u0915\u094d\u0937\u093e \u0915\u0930\u0948 \u092a\u094d\u0930\u093e\u0928 \u0915\u0940\u0965\\n\\n\u092f\u0939 \u092c\u091c\u0930\u0902\u0917 \u092c\u093e\u0923 \u091c\u094b \u091c\u093e\u092a\u0948\u0964\\n\u0924\u093e\u0938\u094b\u0902 \u092d\u0942\u0924-\u092a\u094d\u0930\u0947\u0924 \u0938\u092c \u0915\u093e\u0902\u092a\u0948\u0965\\n\u0927\u0942\u092a \u0926\u0947\u092f \u0905\u0930\u0941 \u091c\u092a\u0948 \u0939\u092e\u0947\u0936\u093e\u0964\\n\u0924\u093e\u0915\u0947 \u0924\u0928 \u0928\u0939\u093f\u0902 \u0930\u0939\u0948 \u0915\u0932\u0947\u0938\u093e\u0965\\n\\n\u0965 \u0926\u094b\u0939\u093e \u0965\\n\u0909\u0930 \u092a\u094d\u0930\u0924\u0940\u0924\u093f \u0926\u0943\u095d, \u0938\u0930\u0928 \u0939\u094d\u0935\u0948, \u092a\u093e\u0920 \u0915\u0930\u0948 \u0927\u0930\u093f \u0927\u094d\u092f\u093e\u0928\u0964\\n\u092c\u093e\u0927\u093e \u0938\u092c \u0939\u0930, \u0915\u0930\u0948\u0902 \u0938\u092c \u0915\u093e\u092e \u0938\u092b\u0932 \u0939\u0928\u0941\u092e\u093e\u0928\u0965\"}, {\"track_key\": \"bhairav_aarti\", \"title_hindi\": \"\u0936\u094d\u0930\u0940 \u092d\u0948\u0930\u0935 \u091c\u0940 \u0915\u0940 \u0906\u0930\u0924\u0940 (\u0938\u0941\u0928\u094b \u091c\u0940 \u092d\u0948\u0930\u0935 \u0932\u093e\u0921\u0932\u0947)\", \"title_english\": \"Shri Bhairav Ladle Aarti\", \"subtitle_hindi\": \"\u0938\u0941\u0928\u094b \u091c\u0940 \u092d\u0948\u0930\u0935 \u0932\u093e\u0921\u0932\u0947, \u0915\u0930 \u091c\u094b\u0921\u093c \u0915\u0930 \u0935\u093f\u0928\u0924\u0940 \u0915\u0930\u0942\u0901\", \"duration_text\": \"4:45\", \"audio_url\": \"https://shribalajikripadham.online/uploads/audio/sbkd_audio_1791373307_b8cfc4.mp3\", \"display_order\": 6, \"is_published\": 1, \"youtube_search_query\": \"Shri Bhairav Dev Aarti\", \"lyrics_hindi\": \"\u0938\u0941\u0928\u094b \u091c\u0940 \u092d\u0948\u0930\u0935 \u0932\u093e\u0921\u0932\u0947, \u0915\u0930 \u091c\u094b\u0921\u093c \u0915\u0930 \u0935\u093f\u0928\u0924\u0940 \u0915\u0930\u0942\u0901\u0964\\n\u0915\u0943\u092a\u093e \u0924\u0941\u092e\u094d\u0939\u093e\u0930\u0940 \u091a\u093e\u0939\u093f\u090f, \u092e\u0948\u0902 \u0927\u094d\u092f\u093e\u0928 \u0924\u0941\u092e\u094d\u0939\u093e\u0930\u093e \u0939\u0940 \u0927\u0930\u0942\u0901\u0965 (\u0927\u094d\u0930\u0941\u0935\u092a\u0926)\\n\\n\u092e\u0948\u0902 \u091a\u0930\u0923 \u091b\u0942\u0924\u093e \u0906\u092a\u0915\u0947, \u0905\u0930\u094d\u091c\u0940 \u092e\u0947\u0930\u0940 \u0938\u0941\u0928 \u0932\u0940\u091c\u093f\u090f\u0964\\n\u092e\u0948\u0902 \u0939\u0942\u0901 \u092e\u0924\u093f \u0915\u093e \u092e\u0902\u0926, \u092e\u0947\u0930\u0940 \u0915\u0941\u091b \u092e\u0926\u0926 \u0924\u094b \u0915\u0940\u091c\u093f\u090f\u0965\\n\u092e\u0939\u093f\u092e\u093e \u0924\u0941\u092e\u094d\u0939\u093e\u0930\u0940 \u092c\u0939\u0941\u0924, \u0915\u0941\u091b \u0925\u094b\u0921\u093c\u0940 \u0938\u0940 \u092e\u0948\u0902 \u0935\u0930\u094d\u0923\u0928 \u0915\u0930\u0942\u0901\u0964\\n\u0938\u0941\u0928\u094b \u091c\u0940 \u092d\u0948\u0930\u0935 \u0932\u093e\u0921\u0932\u0947, \u0915\u0930 \u091c\u094b\u0921\u093c \u0915\u0930 \u0935\u093f\u0928\u0924\u0940 \u0915\u0930\u0942\u0901\u0965\\n\\n\u0915\u0930\u0924\u0947 \u0938\u0935\u093e\u0930\u0940 \u0936\u094d\u0935\u093e\u0928 \u0915\u0940, \u091a\u093e\u0930\u094b\u0902 \u0926\u093f\u0936\u093e \u092e\u0947\u0902 \u0930\u093e\u091c\u094d\u092f \u0939\u0948\u0964\\n\u091c\u093f\u0924\u0928\u0947 \u092d\u0942\u0924 \u0914\u0930 \u092a\u094d\u0930\u0947\u0924, \u0938\u092c\u0915\u0947 \u0906\u092a \u0939\u0940 \u0938\u0930\u0924\u093e\u091c \u0939\u0948\u0902\u0965\\n\u0939\u0925\u093f\u092f\u093e\u0930 \u0939\u0948 \u091c\u094b \u0906\u092a\u0915\u0947, \u0909\u0928\u0915\u093e \u0915\u094d\u092f\u093e \u0935\u0930\u094d\u0923\u0928 \u0915\u0930\u0942\u0901\u0964\\n\u0938\u0941\u0928\u094b \u091c\u0940 \u092d\u0948\u0930\u0935 \u0932\u093e\u0921\u0932\u0947, \u0915\u0930 \u091c\u094b\u0921\u093c \u0915\u0930 \u0935\u093f\u0928\u0924\u0940 \u0915\u0930\u0942\u0901\u0965\\n\\n\u092e\u093e\u0924\u093e\u091c\u0940 \u0915\u0947 \u0938\u093e\u092e\u0928\u0947 \u0924\u0941\u092e, \u0928\u0943\u0924\u094d\u092f \u092d\u0940 \u0915\u0930\u0924\u0947 \u0939\u094b \u0938\u0926\u093e\u0964\\n\u0917\u093e-\u0917\u093e \u0915\u0947 \u0917\u0941\u0923-\u0905\u0928\u0941\u0935\u093e\u0926 \u0938\u0947, \u0909\u0928\u0915\u094b \u0930\u093f\u091d\u093e\u0924\u0947 \u0939\u094b \u0938\u0926\u093e\u0965\\n\u090f\u0915 \u0938\u093e\u0902\u0915\u0932\u0940 \u0939\u0948 \u0906\u092a\u0915\u0940, \u0924\u093e\u0930\u0940\u092b\u093c \u0909\u0938\u0915\u0940 \u0915\u094d\u092f\u093e \u0915\u0930\u0942\u0901\u0964\\n\u0938\u0941\u0928\u094b \u091c\u0940 \u092d\u0948\u0930\u0935 \u0932\u093e\u0921\u0932\u0947, \u0915\u0930 \u091c\u094b\u0921\u093c \u0915\u0930 \u0935\u093f\u0928\u0924\u0940 \u0915\u0930\u0942\u0901\u0965\\n\\n\u092c\u0939\u0941\u0924 \u0938\u0940 \u092e\u0939\u093f\u092e\u093e \u0924\u0941\u092e\u094d\u0939\u093e\u0930\u0940, \u092e\u0947\u0939\u0902\u0926\u0940\u092a\u0941\u0930 \u0938\u0930\u0928\u093e\u092e \u0939\u0948\u0964\\n\u0906\u0924\u0947 \u091c\u0917\u0924 \u0915\u0947 \u092f\u093e\u0924\u094d\u0930\u0940, \u092c\u091c\u0930\u0902\u0917 \u0915\u093e \u0938\u094d\u0925\u093e\u0928 \u0939\u0948\u0965\\n\u0936\u094d\u0930\u0940 \u092a\u094d\u0930\u0947\u0924\u0930\u093e\u091c \u0938\u0930\u0915\u093e\u0930 \u0915\u0947, \u092e\u0948\u0902 \u0936\u0940\u0936 \u091a\u0930\u0923\u094b\u0902 \u092e\u0947\u0902 \u0927\u0930\u0942\u0901\u0964\\n\u0938\u0941\u0928\u094b \u091c\u0940 \u092d\u0948\u0930\u0935 \u0932\u093e\u0921\u0932\u0947, \u0915\u0930 \u091c\u094b\u0921\u093c \u0915\u0930 \u0935\u093f\u0928\u0924\u0940 \u0915\u0930\u0942\u0901\u0965\\n\\n\u0921\u0942\u0901\u0917\u0930\u093e \u091c\u093e\u091f \u0915\u0947 \u0927\u093e\u092e \u092e\u0947\u0902, \u092c\u093e\u092c\u093e \u0924\u093f\u0939\u093e\u0930\u0940 \u0936\u093e\u0928 \u0939\u0948\u0964\\n\u0938\u0902\u0915\u091f \u0915\u091f\u0947 \u0938\u092c \u092d\u0915\u094d\u0924 \u0915\u0947, \u092e\u093f\u0932\u0924\u093e \u0905\u092d\u092f \u0935\u0930\u0926\u093e\u0928 \u0939\u0948\u0965\\n\u0926\u0941\u0916\u093f\u092f\u094b\u0902 \u0915\u0947 \u0938\u0902\u0915\u091f \u0926\u0942\u0930 \u0915\u0930, \u091a\u0930\u0923\u094b\u0902 \u092e\u0947\u0902 \u0924\u0947\u0930\u0947 \u0906 \u0917\u093f\u0930\u0942\u0901\u0964\\n\u0938\u0941\u0928\u094b \u091c\u0940 \u092d\u0948\u0930\u0935 \u0932\u093e\u0921\u0932\u0947, \u0915\u0930 \u091c\u094b\u0921\u093c \u0915\u0930 \u0935\u093f\u0928\u0924\u0940 \u0915\u0930\u0942\u0901\u0965\\n\\n\u0928\u093f\u0936\u0926\u093f\u0928 \u0924\u0941\u092e\u094d\u0939\u093e\u0930\u0947 \u0916\u0947\u0932 \u0938\u0947, \u092e\u093e\u0924\u093e\u091c\u0940 \u0916\u0941\u0936 \u0939\u094b\u0924\u0940 \u0930\u0939\u0947\u0902\u0964\\n\u0938\u0930 \u092a\u0930 \u0924\u0941\u092e\u094d\u0939\u093e\u0930\u0947 \u0939\u093e\u0925 \u0930\u0916\u0915\u0930, \u0906\u0936\u0940\u0930\u094d\u0935\u093e\u0926 \u0926\u0947\u0924\u0940 \u0930\u0939\u0947\u0902\u0965\\n\u0915\u0930 \u091c\u094b\u0921\u093c \u0915\u0930 \u0935\u093f\u0928\u0924\u0940 \u0915\u0930\u0942\u0901, \u0914\u0930 \u0936\u0940\u0936 \u091a\u0930\u0923\u094b\u0902 \u092e\u0947\u0902 \u0927\u0930\u0942\u0901\u0964\\n\u0938\u0941\u0928\u094b \u091c\u0940 \u092d\u0948\u0930\u0935 \u0932\u093e\u0921\u0932\u0947, \u0915\u0930 \u091c\u094b\u0921\u093c \u0915\u0930 \u0935\u093f\u0928\u0924\u0940 \u0915\u0930\u0942\u0901\u0965\"}, {\"track_key\": \"pretraj_chalisa\", \"title_hindi\": \"\u0936\u094d\u0930\u0940 \u092a\u094d\u0930\u0947\u0924\u0930\u093e\u091c \u0938\u0930\u0915\u093e\u0930 \u0915\u0940 \u0906\u0930\u0924\u0940 \u0935 \u091a\u093e\u0932\u0940\u0938\u093e\", \"title_english\": \"Shri Pretraj Sarkar Aarti & Chalisa\", \"subtitle_hindi\": \"\u0938\u0902\u0915\u091f \u092d\u0902\u091c\u0928 \u2022 \u0926\u0941\u0937\u094d\u091f \u0926\u0932\u0928 \u2022 \u0938\u0902\u092a\u0942\u0930\u094d\u0923 \u092a\u093e\u0920\", \"duration_text\": \"6:30\", \"audio_url\": \"https://shribalajikripadham.online/uploads/audio/sbkd_audio_1791373308_2b4b4b.mp3\", \"display_order\": 7, \"is_published\": 1, \"youtube_search_query\": \"Shri Pretraj Sarkar Chalisa\", \"lyrics_hindi\": \"\u0965 \u0936\u094d\u0930\u0940 \u092a\u094d\u0930\u0947\u0924\u0930\u093e\u091c \u0938\u0930\u0915\u093e\u0930 \u0915\u0940 \u0928\u093f\u0924\u094d\u092f \u0906\u0930\u0924\u0940 \u0965\\n\u0950 \u091c\u092f \u092a\u094d\u0930\u0947\u0924\u0930\u093e\u091c \u0915\u0943\u092a\u093e\u0932\u093e, \u092a\u094d\u0930\u092d\u0941 \u091c\u092f \u092a\u094d\u0930\u0947\u0924\u0930\u093e\u091c \u0915\u0943\u092a\u093e\u0932\u093e\u0964\\n\u0926\u0941\u0937\u094d\u091f \u0926\u0932\u0928 \u092a\u093e\u0935\u0928 \u092d\u0917\u0935\u093e\u0928\u093e, \u0938\u0902\u0915\u091f \u0939\u0930\u0928 \u0926\u092f\u093e\u0932\u093e\u0965 \u0950 \u091c\u092f \u092a\u094d\u0930\u0947\u0924\u0930\u093e\u091c \u0915\u0943\u092a\u093e\u0932\u093e...\\n\\n\u0905\u0938\u0941\u0930 \u0928\u093f\u0915\u0902\u0926\u0928 \u0924\u0947\u091c \u092a\u094d\u0930\u0924\u093e\u092a\u0940, \u092d\u0915\u094d\u0924\u0928 \u0915\u0947 \u092a\u094d\u0930\u0924\u093f\u092a\u093e\u0932\u093e\u0964\\n\u0936\u094d\u0930\u0940 \u092c\u093e\u0932\u093e\u091c\u0940 \u0938\u0902\u0917 \u0935\u093f\u0930\u093e\u091c\u0947, \u092e\u0939\u093f\u092e\u093e \u0905\u0924\u093f \u0935\u093f\u0936\u093e\u0932\u093e\u0965 \u0950 \u091c\u092f \u092a\u094d\u0930\u0947\u0924\u0930\u093e\u091c \u0915\u0943\u092a\u093e\u0932\u093e...\\n\\n\u092d\u0942\u0924 \u092a\u093f\u0936\u093e\u091a \u092f\u0915\u094d\u0937 \u092c\u0947\u0924\u093e\u0932\u093e, \u0915\u093e\u0902\u092a\u0924 \u0925\u0930-\u0925\u0930 \u0915\u093e\u092f\u093e\u0964\\n\u0924\u0941\u092e\u094d\u0939\u0930\u0947 \u092d\u091c\u0928 \u0938\u0947 \u092d\u093e\u0917\u0924 \u0938\u0902\u0915\u091f, \u091b\u093f\u0928 \u092e\u0947\u0902 \u0926\u0942\u0930 \u092e\u094b\u0939-\u092e\u093e\u092f\u093e\u0965 \u0950 \u091c\u092f \u092a\u094d\u0930\u0947\u0924\u0930\u093e\u091c \u0915\u0943\u092a\u093e\u0932\u093e...\\n\\n\u091a\u094c\u0915\u0940 \u092a\u0930 \u092a\u094d\u0930\u092d\u0941 \u0930\u0942\u092a \u0938\u0941\u0939\u093e\u0935\u0947, \u0939\u093e\u0925 \u0916\u0921\u0917 \u0938\u094b\u0939\u0947\u0964\\n\u0926\u0941\u0916\u093f\u092f\u094b\u0902 \u0915\u0947 \u0926\u0941\u0916 \u0926\u0942\u0930 \u0915\u0930\u0924 \u0939\u094b, \u0924\u094d\u0930\u093f\u092d\u0941\u0935\u0928 \u091c\u0928 \u092e\u094b\u0939\u0947\u0965 \u0950 \u091c\u092f \u092a\u094d\u0930\u0947\u0924\u0930\u093e\u091c \u0915\u0943\u092a\u093e\u0932\u093e...\\n\\n\u0926\u0902\u0921 \u092a\u094d\u0930\u091a\u0902\u0921 \u0924\u0941\u092e\u094d\u0939\u093e\u0930\u094b \u0938\u094d\u0935\u093e\u092e\u0940, \u0926\u0941\u0937\u094d\u091f\u0928 \u0915\u094b \u0938\u0902\u0939\u093e\u0930\u0947\u0964\\n\u091c\u094b \u091c\u0928 \u0936\u0930\u0923 \u0924\u0941\u092e\u094d\u0939\u093e\u0930\u0940 \u0906\u090f, \u0924\u093f\u0928\u0915\u0947 \u0915\u093e\u091c \u0938\u0902\u0935\u093e\u0930\u0947\u0965 \u0950 \u091c\u092f \u092a\u094d\u0930\u0947\u0924\u0930\u093e\u091c \u0915\u0943\u092a\u093e\u0932\u093e...\\n\\n\u0915\u0902\u091a\u0928 \u0925\u093e\u0932 \u0915\u092a\u0942\u0930 \u0938\u0941\u0939\u093e\u0908, \u0906\u0930\u0924\u0940 \u0915\u0930\u0924 \u092a\u0941\u0915\u093e\u0930\u0940\u0964\\n\u091c\u092f \u092a\u094d\u0930\u0947\u0924\u0930\u093e\u091c \u0926\u0947\u0935 \u0926\u092f\u093e\u0932\u093e, \u0935\u093f\u092a\u0926\u093e \u0939\u0930\u094b \u0939\u092e\u093e\u0930\u0940\u0965 \u0950 \u091c\u092f \u092a\u094d\u0930\u0947\u0924\u0930\u093e\u091c \u0915\u0943\u092a\u093e\u0932\u093e...\\n\\n\u0906\u0930\u0924\u0940 \u091c\u094b \u0915\u094b\u0908 \u0928\u0930-\u0928\u093e\u0930\u0940 \u0917\u093e\u0935\u0947, \u092e\u0928\u0935\u093e\u0902\u091b\u093f\u0924 \u092b\u0932 \u092a\u093e\u0935\u0947\u0964\\n\u0915\u0939\u0924 \u0926\u093e\u0938 \u092a\u094d\u0930\u092d\u0941 \u0936\u0930\u0923 \u0924\u093f\u0939\u093e\u0930\u0940, \u092f\u092e \u0915\u093e \u092d\u092f \u0928 \u0938\u0924\u093e\u0935\u0947\u0965 \u0950 \u091c\u092f \u092a\u094d\u0930\u0947\u0924\u0930\u093e\u091c \u0915\u0943\u092a\u093e\u0932\u093e...\\n\\n\u0965 \u0936\u094d\u0930\u0940 \u092a\u094d\u0930\u0947\u0924\u0930\u093e\u091c \u0938\u0930\u0915\u093e\u0930 \u091a\u093e\u0932\u0940\u0938\u093e \u0965\\n\u0965 \u0926\u094b\u0939\u093e \u0965\\n\u0938\u0941\u092e\u093f\u0930\u093f \u091a\u0930\u0923 \u092a\u094d\u0930\u0947\u0924\u0930\u093e\u091c \u0915\u0947, \u0927\u0930\u092e \u0927\u0941\u0930\u0902\u0927\u0930 \u0927\u0940\u0930\u0964\\n\u0939\u0930\u0939\u0941 \u0938\u0915\u0932 \u092d\u0935 \u0906\u092a\u0926\u093e, \u092e\u0947\u091f\u0939\u0941 \u091c\u0928 \u0915\u0940 \u092a\u0940\u0930\u0965\\n\\n\u0965 \u091a\u094c\u092a\u093e\u0908 \u0965\\n\u091c\u092f \u091c\u092f \u091c\u092f \u092a\u094d\u0930\u0947\u0924\u0930\u093e\u091c \u092c\u0932\u093f\u0935\u093e\u0928\u093e\u0964 \u0926\u0941\u0937\u094d\u091f \u0926\u0932\u0928 \u092a\u093e\u0935\u0928 \u092d\u0917\u0935\u093e\u0928\u093e\u0965\\n\u0924\u0941\u092e \u0938\u0941\u0917\u094d\u0930\u0940\u0935 \u0930\u093e\u092e \u0915\u0947 \u0926\u093e\u0938\u093e\u0964 \u092a\u0942\u0930\u0928 \u0915\u0930\u0939\u0941 \u092d\u0915\u094d\u0924 \u0905\u092d\u093f\u0932\u093e\u0937\u093e\u0965\\n\u0936\u094d\u0930\u0940 \u092c\u093e\u0932\u093e\u091c\u0940 \u0915\u0947 \u0938\u0902\u0917 \u0935\u093f\u0930\u093e\u091c\u0947\u0964 \u091a\u094c\u0915\u0940 \u092a\u0930 \u092a\u094d\u0930\u092d\u0941 \u0930\u0942\u092a \u0938\u0941\u0939\u093e\u091c\u0947\u0965\\n\u092d\u0942\u0924 \u092a\u093f\u0936\u093e\u091a \u0921\u093e\u0915\u093f\u0928\u0940 \u092d\u093e\u0917\u0940\u0964 \u0924\u0941\u092e\u094d\u0939\u0930\u0940 \u0936\u0930\u0923 \u091c\u094b \u092a\u094d\u0930\u093e\u0923\u0940 \u0932\u093e\u0917\u0940\u0965\\n\u0930\u094b\u0917 \u0926\u094b\u0937 \u0938\u092c \u092a\u0932 \u092e\u0947\u0902 \u091f\u093e\u0930\u094b\u0964 \u0915\u0943\u092a\u093e \u0926\u0943\u0937\u094d\u091f\u093f \u0915\u0930 \u092d\u0915\u094d\u0924 \u0909\u092c\u093e\u0930\u094b\u0965\\n\u091c\u094b \u091c\u0928 \u0927\u094d\u092f\u093e\u0928 \u0927\u0930\u0947 \u092e\u0928 \u0932\u093e\u0908\u0964 \u0924\u093e\u0915\u0947 \u0938\u0902\u0915\u091f \u0926\u0947\u0939\u0941 \u092e\u093f\u091f\u093e\u0908\u0965\\n\u091c\u092f \u092a\u094d\u0930\u0947\u0924\u0930\u093e\u091c \u0926\u0947\u0935 \u0926\u092f\u093e\u0932\u093e\u0964 \u0938\u0926\u093e \u0915\u0930\u0939\u0941 \u092d\u0915\u094d\u0924\u0928 \u092a\u094d\u0930\u0924\u093f\u092a\u093e\u0932\u093e\u0965\\n\u0905\u0938\u0941\u0930 \u0928\u093f\u0915\u0902\u0926\u0928 \u092a\u0930\u092e \u092a\u094d\u0930\u0924\u093e\u092a\u0940\u0964 \u0915\u093e\u0902\u092a\u0924 \u0925\u0930-\u0925\u0930 \u0905\u0927\u092e\u0940 \u092a\u093e\u092a\u0940\u0965\\n\u092d\u0948\u0930\u0935 \u0938\u0902\u0917 \u0924\u0941\u092e\u094d\u0939\u093e\u0930\u0940 \u091c\u094b\u095c\u0940\u0964 \u092e\u0939\u093f\u092e\u093e \u0915\u0939\u0940 \u0928 \u091c\u093e\u092f \u0928\u093f\u0939\u094b\u0930\u0940\u0965\\n\u0939\u093e\u0925 \u092e\u0947\u0902 \u0938\u094b\u091f\u093e \u0916\u0921\u094d\u0917 \u0935\u093f\u0930\u093e\u091c\u0947\u0964 \u0926\u0941\u0937\u094d\u091f \u0926\u0932\u0928 \u0930\u0923 \u0921\u0902\u0915\u093e \u092c\u093e\u091c\u0947\u0965\\n\u091c\u094b \u091c\u0928 \u0905\u0930\u094d\u091c\u0940 \u0927\u093e\u092e \u0932\u0917\u093e\u0935\u0947\u0964 \u092a\u094d\u0930\u0947\u0924\u0930\u093e\u091c \u0924\u093e\u0915\u0947 \u0915\u0937\u094d\u091f \u0928\u0936\u093e\u0935\u0947\u0965\\n\u092a\u0930\u092e \u092a\u0941\u0928\u0940\u0924 \u0927\u093e\u092e \u0915\u0932\u094d\u092f\u093e\u0923\u093e\u0964 \u0921\u0942\u0901\u0917\u0930\u093e \u091c\u093e\u091f \u092e\u0939\u093f\u092e\u093e \u091c\u0917 \u091c\u093e\u0928\u093e\u0965\\n\u0917\u0941\u0930\u0941\u0926\u0947\u0935 \u0924\u0947\u091c\u0935\u0940\u0930 \u0915\u0940 \u092c\u093e\u0928\u0940\u0964 \u0938\u0902\u0915\u091f \u0915\u091f\u0947 \u0938\u0941\u0916\u0940 \u0939\u094b \u092a\u094d\u0930\u093e\u0923\u0940\u0965\\n\u091c\u094b \u092f\u0939 \u091a\u093e\u0932\u0940\u0938\u093e \u0928\u093f\u0924 \u0927\u094d\u092f\u093e\u0935\u0948\u0964 \u0938\u0930\u094d\u0935 \u0938\u0941\u0916\u094b\u0902 \u0915\u093e \u092d\u094b\u0917 \u0932\u0917\u093e\u0935\u0948\u0965\\n\u092a\u0941\u0924\u094d\u0930 \u092a\u094c\u0924\u094d\u0930 \u0927\u0928 \u0927\u093e\u0928\u094d\u092f \u092c\u095d\u093e\u0935\u0948\u0964 \u0905\u0928\u094d\u0924 \u0915\u093e\u0932 \u092a\u094d\u0930\u092d\u0941 \u092a\u0926 \u0915\u094b \u092a\u093e\u0935\u0948\u0965\\n\\n\u0965 \u0926\u094b\u0939\u093e \u0965\\n\u092a\u094d\u0930\u0947\u0924\u0930\u093e\u091c \u0938\u0930\u0915\u093e\u0930 \u0915\u0940, \u091c\u094b \u0928\u093f\u0924 \u0906\u0930\u0924\u0940 \u0917\u093e\u092f\u0964\\n\u0938\u0915\u0932 \u0915\u0932\u0947\u0936 \u092c\u093f\u0915\u093e\u0930 \u092e\u093f\u091f\u0947\u0902, \u092a\u0930\u092e\u093e\u0928\u0928\u094d\u0926 \u0938\u092e\u093e\u092f\u0902\u0965\"}, {\"track_key\": \"guru_vandana\", \"title_hindi\": \"\u0936\u094d\u0930\u0940 \u0917\u0941\u0930\u0941\u0926\u0947\u0935 \u091c\u0940 \u0915\u0940 \u0906\u0930\u0924\u0940\", \"title_english\": \"Shri Gurudev Ji Ki Aarti\", \"subtitle_hindi\": \"\u091c\u092f \u0917\u0941\u0930\u0941\u0926\u0947\u0935 \u0926\u092f\u093e\u0928\u093f\u0927\u093f, \u0926\u0940\u0928\u0928 \u0939\u093f\u0924\u0915\u093e\u0930\u0940\", \"duration_text\": \"5:10\", \"audio_url\": \"https://shribalajikripadham.online/uploads/audio/sbkd_audio_1791373309_c31a75.mp3\", \"display_order\": 8, \"is_published\": 1, \"youtube_search_query\": \"Guru Vandana Shloka Anuradha Paudwal\", \"lyrics_hindi\": \"\u091c\u092f \u0917\u0941\u0930\u0941\u0926\u0947\u0935 \u0926\u092f\u093e\u0928\u093f\u0927\u093f, \u0926\u0940\u0928\u0928 \u0939\u093f\u0924\u0915\u093e\u0930\u0940\u0964\\n\u0938\u094d\u0935\u093e\u092e\u0940 \u092d\u0915\u094d\u0924\u0928 \u0939\u093f\u0924\u0915\u093e\u0930\u0940\u0964\\n\u091c\u092f \u091c\u092f \u092e\u094b\u0939 \u0935\u093f\u0928\u093e\u0936\u0915, \u092d\u0935 \u092c\u0902\u0927\u0928 \u0939\u093e\u0930\u0940\u0965\\n\u0950 \u091c\u092f \u091c\u092f \u091c\u092f \u0917\u0941\u0930\u0941\u0926\u0947\u0935 \u0939\u0930\u0947\u0965 (\u0927\u094d\u0930\u0941\u0935\u092a\u0926)\\n\\n\u092c\u094d\u0930\u0939\u094d\u092e\u093e \u0935\u093f\u0937\u094d\u0923\u0941 \u0938\u0926\u093e \u0936\u093f\u0935, \u0917\u0941\u0930\u0941 \u092e\u0942