947\u0965\"}, {\"track_key\": \"ram_stuti\", \"title_hindi\": \"\u0936\u094d\u0930\u0940 \u0930\u093e\u092e\u091a\u0928\u094d\u0926\u094d\u0930 \u0915\u0943\u092a\u093e\u0932\u0941 \u092d\u091c\u0941 \u092e\u0928\", \"title_english\": \"Shri Ram Stuti\", \"subtitle_hindi\": \"\u0939\u0930\u0923 \u092d\u0935\u092d\u092f \u0926\u093e\u0930\u0941\u0923\u0902 \u2022 \u0917\u094b\u0938\u094d\u0935\u093e\u092e\u0940 \u0924\u0941\u0932\u0938\u0940\u0926\u093e\u0938 \u0915\u0943\u0924\", \"duration_text\": \"5:10\", \"audio_url\": \"https://shribalajikripadham.online/uploads/audio/sbkd_audio_1791373306_76412f.mp3\", \"display_order\": 9, \"is_published\": 1, \"youtube_search_query\": \"Shri Ram Chandra Kripalu Bhajman Nitin Mukesh\", \"lyrics_hindi\": \"\u0936\u094d\u0930\u0940\u0930\u093e\u092e\u091a\u0928\u094d\u0926\u094d\u0930 \u0915\u0943\u092a\u093e\u0932\u0941 \u092d\u091c\u0941 \u092e\u0928 \u0939\u0930\u0923 \u092d\u0935\u092d\u092f \u0926\u093e\u0930\u0941\u0923\u0902\u0964\\n\u0928\u0935\u0915\u0902\u091c \u0932\u094b\u091a\u0928, \u0915\u0902\u091c \u092e\u0941\u0916, \u0915\u0930 \u0915\u0902\u091c, \u092a\u0926 \u0915\u0902\u091c\u093e\u0930\u0941\u0923\u0902\u0965 \u0967 \u0965\\n\\n\u0915\u0902\u0926\u0930\u094d\u092a \u0905\u0917\u0923\u093f\u0924 \u0905\u092e\u093f\u0924 \u091b\u092c\u093f, \u0928\u0935\u0928\u0940\u0932 \u0928\u0940\u0930\u0926 \u0938\u0941\u0928\u094d\u0926\u0930\u0902\u0964\\n\u092a\u091f \u092a\u0940\u0924 \u092e\u093e\u0928\u0939\u0941 \u0924\u095c\u093f\u0924 \u0930\u0941\u091a\u093f \u0936\u0941\u091a\u093f \u0928\u094c\u092e\u093f \u091c\u0928\u0915 \u0938\u0941\u0924\u093e\u0935\u0930\u0902\u0965 \u0968 \u0965\\n\\n\u092d\u091c\u0941 \u0926\u0940\u0928\u092c\u0928\u094d\u0927\u0941 \u0926\u093f\u0928\u0947\u0936 \u0926\u093e\u0928\u0935 \u0926\u0948\u0924\u094d\u092f \u0935\u0902\u0936 \u0928\u093f\u0915\u0928\u094d\u0926\u0928\u0902\u0964\\n\u0930\u0918\u0941\u0928\u0928\u094d\u0926 \u0906\u0928\u0928\u094d\u0926\u0915\u0928\u094d\u0926 \u0915\u094b\u0936\u0932\u091a\u0928\u094d\u0926 \u0926\u0936\u0930\u0925 \u0928\u0928\u094d\u0926\u0928\u0902\u0965 \u0969 \u0965\\n\\n\u0938\u093f\u0930 \u092e\u0941\u0915\u0941\u091f \u0915\u0941\u0923\u094d\u0921\u0932 \u0924\u093f\u0932\u0915 \u091a\u093e\u0930\u0941 \u0909\u0926\u093e\u0930\u0941 \u0905\u0919\u094d\u0917 \u0935\u093f\u092d\u0942\u0937\u0923\u0902\u0964\\n\u0906\u091c\u093e\u0928\u0941\u092d\u0941\u091c \u0936\u0930 \u091a\u093e\u092a \u0927\u0930, \u0938\u0902\u0917\u094d\u0930\u093e\u092e-\u091c\u093f\u0924-\u0916\u0930\u0926\u0942\u0937\u0923\u0902\u0965 \u096a \u0965\\n\\n\u0907\u0924\u093f \u0935\u0926\u0924\u093f \u0924\u0941\u0932\u0938\u0940\u0926\u093e\u0938 \u0936\u0902\u0915\u0930 \u0936\u0947\u0937 \u092e\u0941\u0928\u093f \u092e\u0928 \u0930\u0902\u091c\u0928\u0902\u0964\\n\u092e\u092e \u0939\u0943\u0926\u092f \u0915\u0902\u091c \u0928\u093f\u0935\u093e\u0938 \u0915\u0941\u0930\u0941, \u0915\u093e\u092e\u093e\u0926\u093f \u0916\u0932 \u0926\u0932 \u0917\u0902\u091c\u0928\u0902\u0965 \u096b \u0965\\n\\n\u092e\u0928\u0941 \u091c\u093e\u0939\u093f\u0902 \u0930\u093e\u091a\u0947\u0909 \u092e\u093f\u0932\u093f\u0939\u093f \u0938\u094b \u092c\u0930\u0941 \u0938\u0939\u091c \u0938\u0941\u0902\u0926\u0930 \u0938\u093e\u0902\u0935\u0930\u094b\u0964\\n\u0915\u0930\u0941\u0928\u093e \u0928\u093f\u0927\u093e\u0928 \u0938\u0941\u091c\u093e\u0928 \u0938\u0940\u0932\u0941 \u0938\u0928\u0947\u0939\u0941 \u091c\u093e\u0928\u0924 \u0930\u093e\u0935\u0930\u094b\u0965\\n\\n\u090f\u0939\u093f \u092d\u093e\u0902\u0924\u093f \u0917\u094c\u0930\u093f \u0905\u0938\u0940\u0938 \u0938\u0941\u0928\u093f \u0938\u093f\u092f \u0938\u0939\u093f\u0924 \u0939\u093f\u092f\u0902 \u0939\u0930\u0937\u0940\u0902 \u0905\u0932\u0940\u0964\\n\u0924\u0941\u0932\u0938\u0940 \u092d\u0935\u093e\u0928\u093f\u0939\u093f \u092a\u0942\u091c\u093f \u092a\u0941\u0928\u093f \u092a\u0941\u0928\u093f \u092e\u0941\u0926\u093f\u0924 \u092e\u0928 \u092e\u0902\u0926\u093f\u0930 \u091a\u0932\u0940\u0965\\n\\n\u0965 \u0938\u094b\u0930\u0920\u093e \u0965\\n\u091c\u093e\u0928\u0940 \u0917\u094c\u0930\u0940 \u0905\u0928\u0941\u0915\u0942\u0932 \u0938\u093f\u092f \u0939\u093f\u092f \u0939\u0930\u0937\u0941 \u0928 \u091c\u093e\u0907 \u0915\u0939\u093f\u0964\\n\u092e\u0902\u091c\u0941\u0932 \u092e\u0902\u0917\u0932 \u092e\u0942\u0932 \u092c\u093e\u092e \u0905\u0902\u0917 \u092b\u0930\u0915\u0928 \u0932\u0917\u0947\u0965\"}, {\"track_key\": \"ganesh_aarti\", \"title_hindi\": \"\u091c\u092f \u0917\u0923\u0947\u0936 \u091c\u092f \u0917\u0923\u0947\u0936 \u0926\u0947\u0935\u093e\", \"title_english\": \"Jai Ganesh Deva\", \"subtitle_hindi\": \"\u092e\u093e\u0924\u093e \u091c\u093e\u0915\u0940 \u092a\u093e\u0930\u094d\u0935\u0924\u0940 \u092a\u093f\u0924\u093e \u092e\u0939\u093e\u0926\u0947\u0935\u093e\", \"duration_text\": \"4:20\", \"audio_url\": \"https://shribalajikripadham.online/uploads/audio/sbkd_audio_1791373310_682644.mp3\", \"display_order\": 10, \"is_published\": 1, \"youtube_search_query\": \"Jai Ganesh Deva Anuradha Paudwal\", \"lyrics_hindi\": \"\u091c\u092f \u0917\u0923\u0947\u0936, \u091c\u092f \u0917\u0923\u0947\u0936, \u091c\u092f \u0917\u0923\u0947\u0936 \u0926\u0947\u0935\u093e\u0964\\n\u092e\u093e\u0924\u093e \u091c\u093e\u0915\u0940 \u092a\u093e\u0930\u094d\u0935\u0924\u0940, \u092a\u093f\u0924\u093e \u092e\u0939\u093e\u0926\u0947\u0935\u093e\u0965 (\u0927\u094d\u0930\u0941\u0935\u092a\u0926)\\n\\n\u090f\u0915 \u0926\u0928\u094d\u0924, \u0926\u092f\u093e\u0935\u0928\u094d\u0924, \u091a\u093e\u0930 \u092d\u0941\u091c\u093e\u0927\u093e\u0930\u0940\u0964\\n\u092e\u093e\u0925\u0947 \u092a\u0930 \u0924\u093f\u0932\u0915 \u0938\u094b\u0939\u0947, \u092e\u0942\u0938\u0947 \u0915\u0940 \u0938\u0935\u093e\u0930\u0940\u0965\\n\u092a\u093e\u0928 \u091a\u0922\u093c\u0947, \u092b\u0942\u0932 \u091a\u0922\u093c\u0947, \u0914\u0930 \u091a\u0922\u093c\u0947 \u092e\u0947\u0935\u093e\u0964\\n\u0932\u0921\u094d\u0921\u0941\u0905\u0928 \u0915\u093e \u092d\u094b\u0917 \u0932\u0917\u0947, \u0938\u0928\u094d\u0924 \u0915\u0930\u0947\u0902 \u0938\u0947\u0935\u093e\u0965 \u091c\u092f \u0917\u0923\u0947\u0936 \u0926\u0947\u0935\u093e...\\n\\n\u0905\u0928\u094d\u0927\u0947 \u0915\u094b \u0906\u0902\u0916 \u0926\u0947\u0924, \u0915\u094b\u0922\u093c\u093f\u0928 \u0915\u094b \u0915\u093e\u092f\u093e\u0964\\n\u092c\u093e\u0902\u091d\u0928 \u0915\u094b \u092a\u0941\u0924\u094d\u0930 \u0926\u0947\u0924, \u0928\u093f\u0930\u094d\u0927\u0928 \u0915\u094b \u092e\u093e\u092f\u093e\u0965\\n\u0926\u0940\u0928\u0928 \u0915\u0940 \u0932\u093e\u091c \u0930\u093e\u0916\u094b, \u0936\u092e\u094d\u092d\u0941-\u0938\u0941\u0924 \u0935\u093e\u0930\u0940\u0964\\n\u0915\u093e\u092e\u0928\u093e \u0915\u094b \u092a\u0942\u0930\u094d\u0923 \u0915\u0930\u094b, \u091c\u0917 \u092c\u0932\u093f\u0939\u093e\u0930\u0940\u0965 \u091c\u092f \u0917\u0923\u0947\u0936 \u0926\u0947\u0935\u093e...\\n\\n'\u0938\u0942\u0930' \u0936\u094d\u092f\u093e\u092e \u0936\u0930\u0923 \u0906\u090f, \u0938\u092b\u0932 \u0915\u0940\u091c\u0947 \u0938\u0947\u0935\u093e\u0964\\n\u092e\u093e\u0924\u093e \u091c\u093e\u0915\u0940 \u092a\u093e\u0930\u094d\u0935\u0924\u0940, \u092a\u093f\u0924\u093e \u092e\u0939\u093e\u0926\u0947\u0935\u093e\u0965\\n\u091c\u092f \u0917\u0923\u0947\u0936, \u091c\u092f \u0917\u0923\u0947\u0936, \u091c\u092f \u0917\u0923\u0947\u0936 \u0926\u0947\u0935\u093e\u0964\\n\u092e\u093e\u0924\u093e \u091c\u093e\u0915\u0940 \u092a\u093e\u0930\u094d\u0935\u0924\u0940, \u092a\u093f\u0924\u093e \u092e\u0939\u093e\u0926\u0947\u0935\u093e\u0965\"}, {\"track_key\": \"durga_aarti\", \"title_hindi\": \"\u091c\u092f \u0905\u092e\u094d\u092c\u0947 \u0917\u094c\u0930\u0940 (\u0926\u0941\u0930\u094d\u0917\u093e \u0906\u0930\u0924\u0940)\", \"title_english\": \"Jai Ambe Gauri\", \"subtitle_hindi\": \"\u092e\u0948\u092f\u093e \u091c\u092f \u0936\u094d\u092f\u093e\u092e\u093e \u0917\u094c\u0930\u0940\", \"duration_text\": \"5:30\", \"audio_url\": \"https://shribalajikripadham.online/uploads/audio/sbkd_audio_1791373310_b59376.mp3\", \"display_order\": 11, \"is_published\": 1, \"youtube_search_query\": \"Jai Ambe Gauri Anuradha Paudwal\", \"lyrics_hindi\": \"\u091c\u092f \u0905\u092e\u094d\u092c\u0947 \u0917\u094c\u0930\u0940, \u092e\u0948\u092f\u093e \u091c\u092f \u0936\u094d\u092f\u093e\u092e\u093e \u0917\u094c\u0930\u0940\u0964\\n\u0924\u0941\u092e\u0915\u094b \u0928\u093f\u0936\u093f\u0926\u093f\u0928 \u0927\u094d\u092f\u093e\u0935\u0924, \u0939\u0930\u093f \u092c\u094d\u0930\u0939\u094d\u092e\u093e \u0936\u093f\u0935\u0930\u0940\u0965 \u091c\u092f \u0905\u092e\u094d\u092c\u0947 \u0917\u094c\u0930\u0940... (\u0927\u094d\u0930\u0941\u0935\u092a\u0926)\\n\\n\u092e\u093e\u0902\u0917 \u0938\u093f\u0928\u094d\u0926\u0942\u0930 \u0935\u093f\u0930\u093e\u091c\u0924, \u091f\u0940\u0915\u094b \u092e\u0943\u0917\u092e\u0926 \u0915\u094b\u0964\\n\u0909\u091c\u094d\u091c\u094d\u0935\u0932 \u0938\u0947 \u0926\u094b\u0909 \u0928\u0948\u0928\u093e, \u091a\u0928\u094d\u0926\u094d\u0930\u0935\u0926\u0928 \u0928\u0940\u0915\u094b\u0965 \u091c\u092f \u0905\u092e\u094d\u092c\u0947 \u0917\u094c\u0930\u0940...\\n\\n\u0915\u0928\u0915 \u0938\u092e\u093e\u0928 \u0915\u0932\u0947\u0935\u0930, \u0930\u0915\u094d\u0924\u093e\u092e\u094d\u092c\u0930 \u0930\u093e\u091c\u0948\u0964\\n\u0930\u0915\u094d\u0924\u092a\u0941\u0937\u094d\u092a \u0917\u0932 \u092e\u093e\u0932\u093e, \u0915\u0923\u094d\u0920\u0928 \u092a\u0930 \u0938\u093e\u091c\u0948\u0965 \u091c\u092f \u0905\u092e\u094d\u092c\u0947 \u0917\u094c\u0930\u0940...\\n\\n\u0915\u0947\u0939\u0930\u093f \u0935\u093e\u0939\u0928 \u0930\u093e\u091c\u0924, \u0916\u0921\u094d\u0917 \u0916\u092a\u094d\u092a\u0930 \u0927\u093e\u0930\u0940\u0964\\n\u0938\u0941\u0930-\u0928\u0930-\u092e\u0941\u0928\u093f\u091c\u0928 \u0938\u0947\u0935\u0924, \u0924\u093f\u0928\u0915\u0947 \u0926\u0941\u0916\u0939\u093e\u0930\u0940\u0965 \u091c\u092f \u0905\u092e\u094d\u092c\u0947 \u0917\u094c\u0930\u0940...\\n\\n\u0915\u093e\u0928\u0928 \u0915\u0941\u0923\u094d\u0921\u0932 \u0936\u094b\u092d\u093f\u0924, \u0928\u093e\u0938\u093e\u0917\u094d\u0930\u0947 \u092e\u094b\u0924\u0940\u0964\\n\u0915\u094b\u091f\u093f\u0915 \u091a\u0928\u094d\u0926\u094d\u0930 \u0926\u093f\u0935\u093e\u0915\u0930, \u0938\u092e \u0930\u093e\u091c\u0924 \u091c\u094d\u092f\u094b\u0924\u093f\u0965 \u091c\u092f \u0905\u092e\u094d\u092c\u0947 \u0917\u094c\u0930\u0940...\\n\\n\u0936\u0941\u092e\u094d\u092d \u0928\u093f\u0936\u0941\u092e\u094d\u092d \u092c\u093f\u0921\u093e\u0930\u0947, \u092e\u0939\u093f\u0937\u093e\u0938\u0941\u0930 \u0918\u093e\u0924\u0940\u0964\\n\u0927\u0942\u092e\u094d\u0930 \u0935\u093f\u0932\u094b\u091a\u0928 \u0928\u0948\u0928\u093e, \u0928\u093f\u0936\u093f\u0926\u093f\u0928 \u092e\u0926\u092e\u093e\u0924\u0940\u0965 \u091c\u092f \u0905\u092e\u094d\u092c\u0947 \u0917\u094c\u0930\u0940...\\n\\n\u091a\u0923\u094d\u0921-\u092e\u0941\u0923\u094d\u0921 \u0938\u0902\u0939\u093e\u0930\u0947, \u0936\u094b\u0923\u093f\u0924 \u092c\u0940\u091c \u0939\u0930\u0947\u0964\\n\u092e\u0927\u0941-\u0915\u0948\u091f\u092d \u0926\u094b\u0909 \u092e\u093e\u0930\u0947, \u0938\u0941\u0930 \u092d\u092f\u0939\u0940\u0928 \u0915\u0930\u0947\u0965 \u091c\u092f \u0905\u092e\u094d\u092c\u0947 \u0917\u094c\u0930\u0940...\\n\\n\u091a\u094c\u0902\u0938\u0920 \u092f\u094b\u0917\u093f\u0928\u0940 \u0917\u093e\u0935\u0924, \u0928\u0943\u0924\u094d\u092f \u0915\u0930\u0924 \u092d\u0948\u0930\u094b\u0902\u0964\\n\u092c\u093e\u091c\u0924 \u0924\u093e\u0932 \u092e\u0943\u0926\u0902\u0917\u093e, \u0905\u0930\u0941 \u092c\u093e\u091c\u0924 \u0921\u092e\u0930\u0942\u0965 \u091c\u092f \u0905\u092e\u094d\u092c\u0947 \u0917\u094c\u0930\u0940...\\n\\n\u0924\u0941\u092e \u0939\u0940 \u091c\u0917 \u0915\u0940 \u092e\u093e\u0924\u093e, \u0924\u0941\u092e \u0939\u0940 \u0939\u094b \u092d\u0930\u094d\u0924\u093e\u0964\\n\u092d\u0915\u094d\u0924\u0928 \u0915\u0940 \u0926\u0941\u0903\u0916 \u0939\u0930\u0924\u093e, \u0938\u0941\u0916 \u0938\u092e\u094d\u092a\u0924\u093f \u0915\u0930\u094d\u0924\u093e\u0965 \u091c\u092f \u0905\u092e\u094d\u092c\u0947 \u0917\u094c\u0930\u0940...\\n\\n\u092d\u0941\u091c\u093e \u091a\u093e\u0930 \u0905\u0924\u093f \u0936\u094b\u092d\u093f\u0924, \u0935\u0930\u092e\u0941\u0926\u094d\u0930\u093e \u0927\u093e\u0930\u0940\u0964\\n\u092e\u0928\u0935\u093e\u0902\u091b\u093f\u0924 \u092b\u0932 \u092a\u093e\u0935\u0924, \u0938\u0947\u0935\u0924 \u0928\u0930 \u0928\u093e\u0930\u0940\u0965 \u091c\u092f \u0905\u092e\u094d\u092c\u0947 \u0917\u094c\u0930\u0940...\\n\\n\u0915\u0902\u091a\u0928 \u0925\u093e\u0932 \u0935\u093f\u0930\u093e\u091c\u0924, \u0905\u0917\u0930 \u0915\u092a\u0942\u0930 \u092c\u093e\u0924\u0940\u0964\\n\u0936\u094d\u0930\u0940 \u092e\u093e\u0932\u0915\u0947\u0924\u0941 \u092e\u0947\u0902 \u0930\u093e\u091c\u0924, \u0915\u094b\u091f\u093f \u0930\u0924\u0928 \u091c\u094d\u092f\u094b\u0924\u093f\u0965 \u091c\u092f \u0905\u092e\u094d\u092c\u0947 \u0917\u094c\u0930\u0940...\\n\\n\u0936\u094d\u0930\u0940 \u0905\u092e\u094d\u092c\u0947 \u091c\u0940 \u0915\u0940 \u0906\u0930\u0924\u0940, \u091c\u094b \u0915\u094b\u0908 \u0928\u0930 \u0917\u093e\u0935\u0948\u0964\\n\u0915\u0939\u0924 \u0936\u093f\u0935\u093e\u0928\u0928\u094d\u0926 \u0938\u094d\u0935\u093e\u092e\u0940, \u0938\u0941\u0916-\u0938\u092e\u094d\u092a\u0924\u093f \u092a\u093e\u0935\u0948\u0965\\n\u091c\u092f \u0905\u092e\u094d\u092c\u0947 \u0917\u094c\u0930\u0940, \u092e\u0948\u092f\u093e \u091c\u092f \u0936\u094d\u092f\u093e\u092e\u093e \u0917\u094c\u0930\u0940\u0964\\n\u0924\u0941\u092e\u0915\u094b \u0928\u093f\u0936\u093f\u0926\u093f\u0928 \u0927\u094d\u092f\u093e\u0935\u0924, \u0939\u0930\u093f \u092c\u094d\u0930\u0939\u094d\u092e\u093e \u0936\u093f\u0935\u0930\u0940\u0965\"}, {\"track_key\": \"shiv_aarti\", \"title_hindi\": \"\u0950 \u091c\u092f \u0936\u093f\u0935 \u0913\u0902\u0915\u093e\u0930\u093e\", \"title_english\": \"Om Jai Shiv Omkara\", \"subtitle_hindi\": \"\u092c\u094d\u0930\u0939\u094d\u092e\u093e \u0935\u09