            ':te' => $t['title_english'],
            ':sh' => $t['subtitle_hindi'],
            ':dt' => $t['duration_text'],
            ':au' => $t['audio_url'],
            ':lh' => $t['lyrics_hindi'],
            ':ip' => $t['is_published'],
            ':do' => $t['display_order'],
            ':yq' => $t['youtube_search_query']
        ]);
        $count++;
    }

    echo json_encode(['success' => true, 'migrated' => $count]);
} catch (Throwable $e) {
    echo json_encode(['success' => false, 'error' => $e->getMessage()]);
}
